INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(67494157, 'Crawling Dragon', '伏地龙', '地を這うドラゴン', 'Normal Monster', 'Dragon', 'EARTH', 5, 1600, 1400, '力量弱小无法飞天的龙，但攻击还是很强的。'),
(38289717, 'Crawling Dragon #2', '贪尸龙', '屍を貪る竜', 'Normal Monster', 'Dinosaur', 'EARTH', 4, 1600, 1200, '什么都能咬碎的恐龙，攻击力十分恐怖。'),
(53713014, 'Crazy Fish', '狂鱼', 'クレイジー・フィッシュ', 'Normal Monster', 'Fish', 'WATER', 4, 1600, 1200, '利用尖锐的头刺撞过来攻击敌人。'),
(96915510, 'Crealtar, the Impcantation Originator', '魔神仪之创造主－祭坛造物者', '魔神儀の創造主－クリオルター', 'Ritual Effect Monster', 'Fiend', 'LIGHT', 10, 3000, 3000, '「魔神仪的祝诞」降临。这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，把手卡的这张卡给对方观看才能发动。选1张手卡丢弃，那之后，等级合计直到10星为止选自己墓地的「魔神仪」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到持有者卡组。 ②：只要这张卡在怪兽区域存在，仪式怪兽以外的自己场上的「魔神仪」怪兽攻击力上升2000，效果无效化。'),
(5780210, 'Creation Resonator', '创造共鸣者', 'クリエイト・リゾネーター', 'Tuner Monster', 'Fiend', 'WIND', 3, 800, 600, '①：自己场上有8星以上的同调怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(15305240, 'Creature Seizure', '虏获装置', '鹵獲装置', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '双方选择自己场上怪兽各1只，那些怪兽的控制权交换。但是这张卡的控制者必须选择自己场上表侧表示存在的通常怪兽。'),
(31036355, 'Creature Swap', '强制转移', '強制転移', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方玩家各自选自身场上1只怪兽。那2只怪兽的控制权交换。这个回合，那些怪兽不能把表示形式变更。'),
(78811937, 'Creeping Darkness', '偷偷靠近的黑暗', '忍び寄る闇', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地2只暗属性怪兽从游戏中除外发动。从卡组把1只暗属性·4星怪兽加入手卡。'),
(52571838, 'Creeping Doom Manta', '偷偷靠近的恶魔蝠鲼', '忍び寄るデビルマンタ', 'Effect Monster', 'Fish', 'WATER', 3, 1300, 1200, '这张卡召唤成功时，陷阱卡不能发动。'),
(49144107, 'Creepy Coney', '死亡兔', 'デス・ウサギ', 'Flip Effect Monster', 'Beast', 'EARTH', 3, 1000, 1900, '反转：衍生物以外的自己场上表侧表示存在的通常怪兽每有1只，给与对方基本分1000分伤害。'),
(49600724, 'Crevice Into the Different Dimension', '通向异次元的缝隙', '異次元への隙間', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '宣言1个属性，选择双方墓地存在的宣言的属性的怪兽合计2只发动。选择的怪兽从游戏中除外。'),
(3294539, 'Crimson Blade Dragon', NULL, NULL, 'Synchro Monster', 'Dragon', 'DARK', 7, 2400, 2600, NULL),
(80321197, 'Crimson Blader', '深红剑士', 'クリムゾン・ブレーダー', 'Synchro Monster', 'Warrior', 'FIRE', 8, 2800, 2600, '调整＋调整以外的怪兽1只以上 ①：这张卡战斗破坏对方怪兽送去墓地的场合发动。下次的对方回合，对方不能把5星以上的怪兽召唤·特殊召唤。'),
(50604072, 'Crimson Blader/Assault Mode', '深红剑士／爆裂', 'クリムゾン・ブレーダー／バスター', 'Effect Monster', 'Warrior', 'FIRE', 10, 3300, 3100, '这张卡不能通常召唤，用「爆裂模式」的效果才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。把1张「爆裂模式」或者有那个卡名记述的卡从卡组加入手卡，这张卡回到卡组。 ②：对方不能把从额外卡组特殊召唤的5星以上的怪兽的效果发动。 ③：这张卡被破坏的场合才能发动。从自己墓地把1只「深红剑士」特殊召唤。'),
(99398682, 'Crimson Call', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(63436931, 'Crimson Dragon', '赤龙', '赤き竜', 'Synchro Monster', 'Dragon', 'LIGHT', 12, NULL, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把有「红龙」的卡名记述的1张魔法·陷阱卡加入手卡。 ②：自己·对方回合，以除「红龙」外的场上1只7星以上的同调怪兽为对象才能发动。这张卡回到额外卡组，和作为对象的怪兽相同等级的1只龙族同调怪兽当作同调召唤从额外卡组特殊召唤。'),
(24566654, 'Crimson Fire', '深红狱炎弹', 'クリムゾン・ヘルフレア', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有「红莲魔龙」存在，给与自己伤害的魔法·陷阱卡由对方发动时才能发动。作为自己受到的那个效果伤害的代替，对方受到那个数值2倍的伤害。'),
(18861006, 'Crimson Firewing Pegasus', '红飞马 焰翼天马', '紅天馬ファイヤー・ウイング・ペガサス', 'Effect Monster', 'Beast', 'FIRE', 6, 2250, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。这个回合，这张卡可以直接攻击。 ②：对方把场上的怪兽的效果发动时才能发动。给与对方这个效果的发动时积累的连锁数量×300伤害，这张卡不会被那些效果破坏。'),
(98173209, 'Crimson Gaia', '深红地狱盖亚', 'クリムゾン・ヘルガイア', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。除「深红狱大地」外的1张「红莲魔龙」或者有那个卡名记述的卡从自己的卡组·墓地加入手卡。 ②：自己的「红莲魔龙」的攻击宣言时才能发动。对方场上的怪兽全部变成里侧守备表示。 ③：场上的怪兽被战斗·效果破坏的场合才能发动。从自己墓地把1只「红莲魔龙」特殊召唤。'),
(38250531, 'Crimson Knight Vampire Bram', '红贵士－吸血鬼・布莱姆', '紅貴士－ヴァンパイア・ブラム', 'XYZ Monster', 'Zombie', 'DARK', 5, 2500, NULL, '不死族5星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤成功的回合，那只怪兽以外的自己怪兽不能攻击。 ②：场上的这张卡被对方破坏送去墓地的下个回合的准备阶段发动。这张卡从墓地守备表示特殊召唤。'),
(14618326, 'Crimson Ninja', '红衣忍者', '赤い忍者', 'Flip Effect Monster', 'Warrior', 'EARTH', 1, 300, 300, '①：这张卡反转的场合，以场上1张表侧表示的陷阱卡或者场上盖放的1张魔法·陷阱卡为对象发动。那张陷阱卡破坏（那张卡在场上盖放中的场合，翻开确认）。'),
(30270176, 'Crimson Nova the Dark Cubic Lord', '暗黑方界神 深红之挪婆', '暗黒方界神クリムゾン・ノヴァ', 'Effect Monster', 'Fiend', 'DARK', 10, 3000, NULL, '这张卡不能通常召唤。把这张卡以外的手卡的「方界」卡3种类给对方观看的场合才能特殊召唤。这个卡名的③的效果1回合只能使用1次。 ①：这张卡不受这张卡以外的原本攻击力是3000以下的怪兽发动的效果影响。 ②：这张卡的攻击破坏怪兽时才能发动。这次战斗阶段中，这张卡只再1次可以攻击。 ③：自己结束阶段发动。双方玩家受到3000伤害。'),
(72664875, 'Crimson Nova Trinity the Dark Cubic Lord', '暗黑方界邪神 深红之挪婆·三神一体', '暗黒方界邪神クリムゾン・ノヴァ・トリニティ', 'Fusion Monster', 'Fiend', 'DARK', 10, 4500, 3000, '「暗黑方界神 深红之挪婆」×3 这张卡用以上记的卡为融合素材的融合召唤才能特殊召唤。 ①：场上的这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ②：这张卡的攻击宣言时发动。对方基本分变成一半。 ③：这张卡的攻击破坏怪兽时才能发动。这次战斗阶段中，这张卡只再1次可以攻击。 ④：自己受到效果伤害的场合发动。给与对方为受到的伤害数值的伤害。'),
(34761841, 'Crimson Resonator', '深红共鸣者', 'クリムゾン・リゾネーター', 'Tuner Monster', 'Fiend', 'DARK', 2, 800, 300, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是龙族·暗属性同调怪兽不能从额外卡组特殊召唤。 ①：这张卡在手卡存在，自己场上没有怪兽存在的场合才能发动。这张卡特殊召唤。 ②：自己场上的其他怪兽只有龙族·暗属性同调怪兽1只的场合才能发动。从手卡·卡组把「深红共鸣者」以外的最多2只「共鸣者」怪兽特殊召唤。'),
(28358902, 'Crimson Sentry', '红莲之女守护兵', '紅蓮の女守護兵', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 1200, '表侧表示的这张卡做祭品。1只这个回合被战斗破坏送去墓地的自己的怪兽回到卡组的最下面。'),
(46696593, 'Crimson Sunbird', '红阳鸟', '紅陽鳥', 'Fusion Monster', 'Winged Beast', 'FIRE', 6, 2300, 1800, '「圣鸟」＋「天空猎手」'),
(18654201, 'Criosphinx', '斯芬克斯 克莱欧', 'クリオスフィンクス', 'Effect Monster', 'Rock', 'EARTH', 6, 1200, 2400, '只要这张卡在自己场上表侧表示存在，场上的怪兽回到持有者手卡时，那只怪兽的持有者从手卡选择1张卡送去墓地。'),
(24082387, 'Crop Circles', '麦田圈', 'ミステリーサークル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上任意数量的怪兽送去墓地发动。从自己卡组选择1只送去墓地的怪兽的合计等级的名字带有「外星」的怪兽特殊召唤。召唤失败的场合，自己受到2000分的伤害。'),
(46961802, 'Cross Attack', '交叉攻击', 'クロス・アタック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧攻击表示存在的2只持有相同攻击力的怪兽发动。这个回合，选择的1只怪兽可以直接攻击对方玩家。另1只怪兽不能攻击。'),
(20862918, 'Cross Breed', '交叉混种', 'クロス・ブリード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把2只原本的种族·属性相同而卡名不同的怪兽除外才能发动。和那些怪兽是原本的种族·属性相同而卡名不同的1只怪兽从卡组加入手卡。'),
(37083210, 'Cross Counter', '交叉反击', 'クロスカウンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '受攻击的守备表示怪兽的守备力，比对方攻击怪兽的攻击力高的场合，给与对方的战斗伤害变成2倍。伤害计算后那只攻击怪兽破坏。'),
(9097866, 'Cross Debug', '交叉调试瓢虫', 'クロス・デバッガー', 'Effect Monster', 'Cyberse', 'DARK', 2, 900, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有连接怪兽2只以上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己和对方的连接怪兽之间进行战斗的伤害计算时，把墓地的这张卡除外，以自己墓地1只连接怪兽为对象才能发动。那只进行战斗的自己怪兽的攻击力直到回合结束时上升作为对象的怪兽的攻击力数值，不会被那次战斗破坏。'),
(40740224, 'Cross Keeper', '交叉看守员', 'クロス・キーパー', 'Effect Monster', 'Warrior', 'DARK', 2, 400, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡送去墓地才能发动。从自己的手卡·墓地选1只「元素英雄」怪兽或者「新空间侠」怪兽特殊召唤。这个效果从墓地特殊召唤的怪兽的效果无效化。 ②：这张卡在墓地存在的状态，自己对「元素英雄」融合怪兽的特殊召唤成功的场合，把这张卡除外才能发动。自己从卡组抽2张，那之后选1张手卡回到卡组最下面。'),
(53241226, 'Cross Over', '跨界交融', 'クロス・オーバー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只表侧表示怪兽和自己场上1只战士族怪兽为对象才能发动。那只对方的表侧表示怪兽当作装备卡使用给那只自己怪兽装备，直到回合结束时那只自己怪兽的战斗发生的对对方的战斗伤害变成0。装备怪兽被战斗·效果破坏的场合，作为代替把用这张卡的效果来装备的怪兽破坏。'),
(73146473, 'Cross Porter', '交叉搬运员', 'クロス・ポーター', 'Effect Monster', 'Warrior', 'DARK', 2, 400, 400, '①：以自己场上1只怪兽为对象才能发动。那只自己怪兽送去墓地，从手卡把1只「新空间侠」怪兽特殊召唤。 ②：这张卡被送去墓地时才能发动。从卡组把1只「新空间侠」怪兽加入手卡。'),
(56889, 'Cross-Dimensional Duel', '竞斗-交叉次元', '競闘－クロス・ディメンション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「古代的机械」怪兽为对象才能发动。那只怪兽除外。这个效果除外的怪兽在下次的准备阶段回到场上，那个攻击力直到那个回合的结束时变成原本攻击力的2倍。 ②：自己场上的「古代的机械巨人」或者「古代的机械巨人-究极重击」被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(50277355, 'Cross-Sheep', '交织绵羊', 'クロシープ', 'Link Monster', 'Beast', 'EARTH', NULL, 700, NULL, '卡名不同的怪兽2只 这个卡名的效果1回合只能使用1次。 ①：这张卡所连接区有怪兽特殊召唤的场合才能发动。这张卡所连接区的怪兽种类的以下效果各适用。 ●仪式：自己抽2张。那之后，选自己2张手卡丢弃。 ●融合：从自己墓地把1只4星以下的怪兽特殊召唤。 ●同调：自己场上的全部怪兽的攻击力上升700。 ●超量：对方场上的全部怪兽的攻击力下降700。'),
(74976215, 'Cross-Sword Beetle', '十字剑猎手', 'クロスソード・ハンター', 'Effect Monster', 'Insect', 'WIND', 4, 1800, 1200, '自己场上有这张卡以外的昆虫族怪兽存在的场合，自己场上存在的昆虫族怪兽攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(52644170, 'Crossmind Archfiend', '心灵交错恶魔', 'メンタルクロス・デーモン', 'Synchro Monster', 'Psychic', 'DARK', 8, 2500, 2800, '念动力族调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以自己的除外状态的1只7星以下的念动力族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己·对方的战斗阶段，把自己场上1只其他怪兽解放才能发动。自己基本分回复那只怪兽的原本攻击力的数值，这张卡的攻击力直到回合结束时上升那个数值。'),
(65681983, 'Crossout Designator', '抹杀之指名者', '抹殺の指名者', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：宣言1个卡名才能发动。宣言的1张卡从卡组除外。这个回合中，这个效果除外的卡以及原本卡名和那张卡相同的卡的效果无效化。'),
(80054655, 'Crossroad Sonic Chick', '叉路小走鹃', 'クロスロードランナー', 'Effect Monster', 'Winged Beast', 'EARTH', 1, 300, 300, '这个卡名的效果1回合只能使用1次。 ①：调整被送去自己墓地的场合才能发动（伤害步骤也能发动）。这张卡从手卡·墓地特殊召唤。除这张卡外的「废品战士」或者有那个卡名记述的怪兽在场上存在的场合，可以再把对方场上的攻击力1900以上的怪兽全部变成守备表示。这个效果特殊召唤的这张卡从场上离开的场合除外。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(72218246, 'Crossrose Dragon', '交错蔷薇龙', 'クロスローズ・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 800, NULL, '种族不同的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把这张卡和自己场上1只植物族怪兽解放才能发动。从额外卡组把1只「蔷薇」同调怪兽或者植物族同调怪兽当作同调召唤作特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的怪兽被效果破坏的场合，把墓地的这张卡除外才能发动。从自己墓地选1只「蔷薇龙」怪兽特殊召唤。'),
(77998771, 'Crow Goblin', '乌鸦天狗', 'カラス天狗', 'Normal Monster', 'Winged Beast', 'WIND', 5, 1850, 1600, '知道各种事的天狗。据说能使用神通之力。'),
(64806765, 'Crow Tengu', '破魔之乌鸦天狗', '破魔のカラス天狗', 'Effect Monster', 'Zombie', 'EARTH', 4, 1400, 1200, '这个卡名的效果1回合只能使用1次。 ①：这张卡被对方的效果破坏送去墓地的场合或者从墓地的特殊召唤成功的场合，以对方场上1只攻击表示怪兽为对象才能发动。那只怪兽破坏。'),
(50756327, 'Crowley, the First Propheseer', '魔导原典 克劳利', '魔導原典 クロウリー', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1000, NULL, '魔法师族怪兽2只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把「魔导书」卡3种类给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩下的卡回到卡组。 ②：只要这张卡在怪兽区域存在，自己在5星以上的魔法师族怪兽召唤的场合需要的解放可以不用。这个效果1回合只能适用1次。'),
(875572, 'Crowley, the Gifted Magistus', '天赋之伟魔导士 克劳利', '天賦の魔導士クロウリー', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「大贤者」融合怪兽或「召唤兽」融合怪兽融合召唤。 ③：把场上的表侧表示的这张卡作为融合素材的场合，可以把卡名当作「召唤师 阿莱斯特」使用。'),
(9505425, 'Crowley, the Magistus of Grimoires', '伟魔贤者 法典之克劳利', '法典の大賢者クロウリー', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1800, 1000, '这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只魔法师族怪兽送去墓地才能发动。这张卡从手卡特殊召唤。 ②：宣言1个属性才能发动。这张卡直到回合结束时变成宣言的属性。 ③：把墓地的这张卡除外，以自己场上1只「大贤者」怪兽为对象才能发动。从自己墓地选1只4星以外的「大贤者」怪兽当作装备卡使用给作为对象的怪兽装备。'),
(95511642, 'Crowned by the World Chalice', '获得星杯的巫女', '星杯を戴く巫女', 'Normal Monster', 'Spellcaster', 'WATER', 2, NULL, 2100, '向星神献上镇魂祈祷的巫女。 手持之杖是世代继承的祭器，将力量变为结界从机界骑士支配中守护着森之民。虽然她的身上隐藏有足以驯服森之守护龙的神通力，但平日所见的她却有着珍爱哥哥及童年玩伴的亲切少女一面。'),
(73853830, 'Crusader of Endymion', '恩底弥翁之十字军', 'クルセイダー・オブ・エンディミオン', 'Gemini Monster', 'Spellcaster', 'LIGHT', 4, 1900, 1200, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●1回合1次，以场上1张可以放置魔力指示物的卡为对象才能发动。给那张卡放置1个魔力指示物，这张卡的攻击力直到回合结束时上升600。'),
(91646304, 'Crusadia Arboria', '神树之圣骑联盟', '神樹のパラディオン', 'Tuner Monster', 'Warrior', 'WATER', 3, 800, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。 ②：自己场上的「圣像骑士」怪兽被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。'),
(54525057, 'Crusadia Draco', '星辰之圣骑联盟', '星辰のパラディオン', 'Effect Monster', 'Dragon', 'WIND', 4, 600, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。 ②：这张卡往连接怪兽所连接区的召唤·特殊召唤成功的场合，以「星辰之圣像骑士」以外的自己墓地1张「圣像骑士」卡为对象才能发动。那张卡加入手卡。'),
(45002991, 'Crusadia Equimax', '穹弧主宰・圣骑联盟', 'アークロード・パラディオン', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2000, NULL, '包含连接怪兽的效果怪兽2只以上 ①：这张卡的攻击力上升这张卡所连接区的怪兽的原本攻击力数值。 ②：这张卡所连接区的怪兽不能攻击。 ③：1回合1次，把这张卡所连接区的自己1只「圣像骑士」怪兽或者「星遗物」怪兽解放，以对方场上1张表侧表示的卡为对象才能发动。那张卡的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(55838342, 'Crusadia Krawler', '机怪虫・圣骑联盟', 'クローラー・パラディオン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（昆虫族·地·2星·攻300/守2100）在怪兽区域特殊召唤。这张卡也当作陷阱卡使用。 ②：这张卡的效果让这张卡往连接怪兽所连接区的特殊召唤成功的场合才能发动。从卡组把1张「星遗物」卡加入手卡。'),
(28031913, 'Crusadia Leonis', '百兽之圣骑联盟', '百獣のパラディオン', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 1600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。 ②：以自己场上1只「圣像骑士」连接怪兽为对象才能发动。这个回合，那只怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(72228247, 'Crusadia Magius', '魔誓・圣骑联盟', 'マギアス・パラディオン', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 100, NULL, '「魔导之圣像骑士」以外的「圣像骑士」怪兽1只 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡所连接区的怪兽的原本攻击力数值。 ②：这张卡所连接区的怪兽不能攻击。 ③：这张卡所连接区有效果怪兽特殊召唤的场合才能发动。从卡组把1只「圣像骑士」怪兽加入手卡。'),
(81524756, 'Crusadia Maximus', '天穹之圣骑联盟', '天穹のパラディオン', 'Effect Monster', 'Psychic', 'LIGHT', 4, 1600, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。 ②：以自己场上1只「圣像骑士」连接怪兽为对象才能发动。这个回合，自己不用那只怪兽不能攻击，那只怪兽用和对方怪兽的战斗给与对方的战斗伤害变成2倍。'),
(96434581, 'Crusadia Power', '戴冠・圣骑联盟', 'オーバード・パラディオン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「圣像骑士」怪兽为对象才能发动。这个回合，那只「圣像骑士」怪兽不受自身以外的卡的效果影响。'),
(55241609, 'Crusadia Reclusia', '魔境之圣骑联盟', '魔境のパラディオン', 'Effect Monster', 'Spellcaster', 'FIRE', 3, 400, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以从手卡往作为连接怪兽所连接区的自己场上守备表示特殊召唤。 ②：这张卡往连接怪兽所连接区的召唤·特殊召唤成功的场合，以自己场上1张「圣像骑士」卡和对方场上1张卡为对象才能发动。那些卡破坏。'),
(9617996, 'Crusadia Regulex', '狮王座・圣骑联盟', 'レグレクス・パラディオン', 'Link Monster', 'Beast', 'LIGHT', NULL, 1000, NULL, '包含「圣像骑士」怪兽的效果怪兽2只 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡所连接区的怪兽的原本攻击力数值。 ②：这张卡所连接区的怪兽不能攻击。 ③：这张卡所连接区有效果怪兽特殊召唤的场合才能发动。从卡组把1张「圣像骑士」魔法·陷阱卡加入手卡。'),
(69039982, 'Crusadia Revival', '复兴・圣骑联盟', 'リユナイト・パラディオン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「圣像骑士」连接怪兽的攻击力上升500。 ②：1回合1次，以自己场上1只「圣像骑士」连接怪兽为对象才能发动。这个回合，自己不用那只怪兽不能攻击，那只怪兽可以向对方怪兽全部各作1次攻击。'),
(39528955, 'Crusadia Spatha', '预言剑巫・圣骑联盟', 'ヴェルスパーダ・パラディオン', 'Link Monster', 'Warrior', 'LIGHT', NULL, 500, NULL, '包含「圣像骑士」怪兽的效果怪兽2只 ①：这张卡的攻击力上升这张卡所连接区的怪兽的原本攻击力数值。 ②：这张卡所连接区的怪兽不能攻击。 ③：1回合1次，这张卡所连接区有效果怪兽特殊召唤的场合，以这张卡以外的自己或者对方的主要怪兽区域1只怪兽为对象才能发动。那只怪兽的位置向其他的主要怪兽区域移动（不能向从那只怪兽来看的对方场上移动）。'),
(87497553, 'Crusadia Testament', '圣约・圣骑联盟', 'テスタメント・パラディオン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●这个回合，对方不能对应自己的「圣像骑士」怪兽的效果的发动把魔法·陷阱·怪兽的效果发动。 ●自己的「圣像骑士」连接怪兽战斗破坏对方怪兽的伤害计算后才能发动。自己从卡组抽出那只自己怪兽的连接标记的数量。'),
(55312487, 'Crusadia Vanguard', '圣战・圣骑联盟', 'クルセイド・パラディオン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡也能把自己场上1只「圣像骑士」怪兽或者「星遗物」怪兽解放来发动。那个场合，从自己的卡组·墓地选原本卡名和那只怪兽不同的1只「圣像骑士」怪兽或者「星遗物」怪兽特殊召唤。 ②：只要自己场上有「圣像骑士」连接怪兽存在，对方只能选择连接怪兽作为攻击对象。'),
(57728570, 'Crush Card Virus', '死之卡组破坏病毒', '死のデッキ破壊ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只攻击力1000以下的暗属性怪兽解放才能发动。对方场上的怪兽以及对方手卡全部确认，那之内的攻击力1500以上的怪兽全部破坏。那之后，对方可以从卡组选最多3只攻击力1500以上的怪兽破坏。这张卡的发动后，直到下个回合的结束时对方受到的全部伤害变成0。'),
(88667504, 'Crusher Run', '超整地破碎', '超整地破砕', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的机械族·地属性怪兽被战斗·效果破坏的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：把墓地的这张卡除外才能发动。从自己的卡组·墓地选1张「超接地展开」或者「超信地旋回」在自己的魔法与陷阱区域盖放。'),
(39712330, 'Cry Havoc!', '决战之火盖', '決戦の火蓋', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '可以把自己墓地1张怪兽卡从游戏中除外，从手卡把1只通常怪兽通常召唤。这个效果在自己回合的主要阶段时才能发动。'),
(23950192, 'Cryomancer of the Ice Barrier', '冰结界的术者', '氷結界の術者', 'Tuner Monster', 'Aqua', 'WATER', 2, 1300, NULL, '①：只要自己场上有其他的「冰结界」怪兽存在，4星以上的怪兽不能攻击宣言。'),
(72881007, 'Crystal Abundance', '宝玉的泛滥', '宝玉の氾濫', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己的魔法与陷阱区域4张表侧表示的「宝玉兽」卡送去墓地才能发动。场上的卡全部送去墓地。那之后，把最多有这个效果从对方场上送去墓地的数量的「宝玉兽」怪兽从自己墓地尽可能特殊召唤。'),
(58371671, 'Crystal Aegis', '宝玉的加护', '宝玉の加護', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1张「宝玉兽」怪兽卡为对象才能发动。那张卡破坏。那之后，把持有那张卡的原本的种族·属性·等级·攻击力·守备力的1只「宝玉兽衍生物」在自己场上特殊召唤。 ②：这张卡在墓地存在，自己的魔法与陷阱区域有「宝玉兽」卡被放置的场合，把这张卡除外才能发动（伤害步骤也能发动）。选自己的魔法与陷阱区域1张「宝玉兽」怪兽卡特殊召唤。'),
(95326659, 'Crystal Beacon', '宝玉的引导', '宝玉の導き', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只「宝玉兽」怪兽特殊召唤。这个效果在自己的魔法与陷阱区域有「宝玉兽」卡2张以上存在的场合才能发动和处理。'),
(69937550, 'Crystal Beast Amber Mammoth', '宝玉兽 琥珀猛犸', '宝玉獣 アンバー・マンモス', 'Effect Monster', 'Beast', 'EARTH', 4, 1700, 1600, '①：这张卡以外的自己的「宝玉兽」怪兽被选择作为攻击对象时才能发动。攻击对象转移为这张卡。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(32933942, 'Crystal Beast Amethyst Cat', '宝玉兽 紫晶猫', '宝玉獣 アメジスト・キャット', 'Effect Monster', 'Beast', 'EARTH', 3, 1200, 400, '①：这张卡可以直接攻击。那次直接攻击给与对方的战斗伤害变成一半。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(21698716, 'Crystal Beast Cobalt Eagle', '宝玉兽 钴尖晶鹰', '宝玉獣 コバルト・イーグル', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1400, 800, '①：1回合1次，以自己场上1张「宝玉兽」卡为对象才能发动。那张自己的「宝玉兽」卡回到持有者卡组最上面。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(68215963, 'Crystal Beast Emerald Tortoise', '宝玉兽 翠玉龟', '宝玉獣 エメラルド・タートル', 'Effect Monster', 'Aqua', 'WATER', 3, 600, 2000, '①：1回合1次，以这个回合进行过攻击的自己场上1只攻击表示怪兽为对象才能发动。那只自己怪兽变成守备表示。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(36795102, 'Crystal Beast Rainbow Dragon', '究极宝玉兽 虹龙', '究極宝玉獣 レインボー・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：「宝玉兽」怪兽进行战斗的攻击宣言时才能发动。这张卡从手卡特殊召唤。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ③：把当作永续魔法卡使用的这张卡除外才能发动。从卡组把1只4星以下的「宝玉兽」怪兽效果无效特殊召唤，从卡组把1只「究极宝玉神」怪兽加入手卡。'),
(32710364, 'Crystal Beast Ruby Carbuncle', '宝玉兽 红玉兽', '宝玉獣 ルビー・カーバンクル', 'Effect Monster', 'Fairy', 'LIGHT', 3, 300, 300, '①：这张卡特殊召唤成功时才能发动。自己的魔法与陷阱区域的「宝玉兽」怪兽卡尽可能特殊召唤。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(7093411, 'Crystal Beast Sapphire Pegasus', '宝玉兽 青玉飞马', '宝玉獣 サファイア・ペガサス', 'Effect Monster', 'Beast', 'WIND', 4, 1800, 1200, '①：这张卡召唤·反转召唤·特殊召唤成功时才能发动。从自己的手卡·卡组·墓地选1只「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(95600067, 'Crystal Beast Topaz Tiger', '宝玉兽 黄玉虎', '宝玉獣 トパーズ・タイガー', 'Effect Monster', 'Beast', 'EARTH', 4, 1600, 1000, '①：这张卡向对方怪兽攻击的伤害步骤内，这张卡的攻击力上升400。 ②：表侧表示的这张卡在怪兽区域被破坏的场合，可以不送去墓地当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(35486099, 'Crystal Blessing', '宝玉的恩惠', '宝玉の恵み', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地最多2只「宝玉兽」怪兽为对象才能发动。那些怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(9334391, 'Crystal Bond', '宝玉的牵绊', '宝玉の絆', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「宝玉兽」怪兽加入手卡，从卡组选和那只怪兽卡名不同的1只「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(85766789, 'Crystal Boon', '宝玉的祝福', '宝玉の祝福', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：选自己的魔法与陷阱区域最多2张「宝玉兽」怪兽卡特殊召唤，自己基本分回复那个原本攻击力合计的数值。 ②：这张卡在墓地存在的状态，自己的魔法与陷阱区域有「宝玉兽」卡被放置的场合，把这张卡除外才能发动（伤害步骤也能发动）。自己卡组最上面的卡翻开，那是「宝玉兽」怪兽的场合，那只怪兽加入手卡或特殊召唤。不是的场合，那张卡送去墓地。'),
(47149093, 'Crystal Brilliance', '宝玉的玲珑', '宝玉の玲瓏', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「宝玉的玲珑」在自己场上只能有1张表侧表示存在。 ②：自己场上的「宝玉兽」怪兽的攻击力上升那原本守备力数值。 ③：自己的魔法与陷阱区域有「宝玉兽」卡被放置的场合，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动（伤害步骤也能发动）。从自己的手卡·墓地选1只「宝玉兽」怪兽特殊召唤。这个回合，自己受到的全部伤害变成一半。'),
(84343351, 'Crystal Clear Wing Over Synchro Dragon', '水晶清透翼超同步龙', 'クリスタルクリアウィング・オーバー・シンクロ・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 12, 3500, 3000, '调整2只以上或者同调怪兽调整＋「幻透翼同调龙」 这张卡不用同调召唤不能特殊召唤。 ①：1回合1次，其他卡的效果发动时才能发动。那个发动无效并破坏。这个效果把怪兽破坏的场合，这张卡的攻击力直到回合结束时上升那个原本攻击力数值。 ②：同调召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。从额外卡组把1只「幻透翼」怪兽特殊召唤。'),
(59765225, 'Crystal Clear Wing Synchro Dragon', '水晶清透翼同步龙', 'クリスタルクリアウィング・シンクロ・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 10, 3000, 2500, '同调怪兽调整＋调整以外的「幻透翼」怪兽1只 ①：1回合1次，对方把怪兽的效果发动时才能发动。这张卡直到回合结束时攻击力上升那只对方怪兽的原本攻击力数值，不受对方发动的怪兽的效果影响。 ②：1回合1次，魔法·陷阱卡的效果发动时才能发动。那个发动无效并破坏。 ③：同调召唤的这张卡被对方送去墓地的场合才能发动。从卡组把1只风属性怪兽加入手卡。'),
(87259933, 'Crystal Conclave', '宝玉的集结', '宝玉の集結', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的①②的效果在同一连锁上不能发动。 ①：1回合1次，自己场上的表侧表示的「宝玉兽」怪兽被战斗·效果破坏的场合才能发动。从卡组把1只「宝玉兽」怪兽特殊召唤。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己场上1张「宝玉兽」卡和场上1张卡为对象才能发动。那些卡回到持有者手卡。'),
(93169863, 'Crystal Girl', '水晶女孩', 'クリスタル・ガール', 'Effect Monster', 'Spellcaster', 'WATER', 1, 200, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。这个回合的结束阶段，从卡组把1只5星以上的水属性怪兽加入手卡。 ②：这张卡在墓地存在，自己场上有5星以上的水属性怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(86999951, 'Crystal God Tistina', '结晶神 提斯蒂娜', '結晶神ティスティナ', 'Effect Monster', 'Aqua', 'LIGHT', 10, 2000, 3000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。对方场上的怪兽全部变成里侧守备表示。那之后，可以把对方场上的表侧表示卡全部送去墓地。 ②：这张卡被对方破坏的场合才能发动。对方场上的怪兽全部变成里侧守备表示。那之后，可以把对方场上的表侧表示卡全部送去墓地。'),
(14469229, 'Crystal Keeper', '宝玉的守护者', '宝玉の守護者', 'Pendulum Effect Monster', 'Warrior', 'FIRE', 4, 1500, 1800, '①：自己的「宝玉兽」怪兽和对方怪兽进行战斗的伤害计算时，把手卡·场上的这张卡解放才能发动。那只进行战斗的自己怪兽攻击力·守备力只在伤害计算时变成原本数值的2倍，伤害步骤结束时破坏。'),
(87475570, 'Crystal Master', '宝玉的先导者', '宝玉の先導者', 'Pendulum Effect Monster', 'Spellcaster', 'DARK', 3, 1300, 1000, '①：把这张卡解放才能发动。「究极宝玉神」怪兽、「宝玉兽」怪兽、「宝玉」魔法·陷阱卡之内任意1张从卡组加入手卡。'),
(11155484, 'Crystal Miracle', '宝玉的奇迹', '宝玉の奇跡', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：怪兽的效果·魔法·陷阱卡发动时才能发动。选自己场上1张「宝玉兽」卡破坏，那个发动无效并破坏。 ②：这张卡在墓地存在的状态，自己的魔法与陷阱区域有「宝玉兽」卡被放置的场合，把这张卡除外才能发动（伤害步骤也能发动）。从自己的手卡·卡组·墓地选1只「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(47121070, 'Crystal Pair', '宝玉的双璧', '宝玉の双璧', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的「宝玉兽」怪兽被战斗破坏送去墓地时才能发动。从卡组选1只「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置，这个回合自己受到的战斗伤害变成0。'),
(8275702, 'Crystal Promise', '宝玉的契约', '宝玉の契約', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的魔法与陷阱区域1张「宝玉兽」怪兽卡为对象才能发动。那张卡特殊召唤。'),
(96331676, 'Crystal Raigeki', '宝玉的祈祷', '宝玉の祈り', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己的魔法与陷阱卡区域存在的1张名字带有「宝玉兽」的卡送去墓地才能发动。对方场上1张卡破坏。'),
(10004783, 'Crystal Release', '宝玉的解放', '宝玉の解放', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「宝玉兽」怪兽才能装备。 ①：装备怪兽的攻击力上升800。 ②：这张卡从场上送去墓地时才能发动。从卡组选1只「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(79531196, 'Crystal Rose', '水晶蔷薇', 'クリスタル・ローズ', 'Effect Monster', 'Rock', 'LIGHT', 2, 500, 500, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己主要阶段才能发动。从手卡·卡组把1只「宝石骑士」怪兽或「幻奏」怪兽送去墓地。这张卡直到结束阶段当作和送去墓地的怪兽同名卡使用。 ②：这张卡在墓地存在的场合，从自己墓地把1只融合怪兽除外才能发动。这张卡守备表示特殊召唤。'),
(82099401, 'Crystal Seer', '水晶占卜师', '水晶の占い師', 'Flip Effect Monster', 'Spellcaster', 'WATER', 1, 100, 100, '反转：从自己卡组上面翻开2张卡，选择那之内的1张加入手卡。剩下的回到卡组最下面。'),
(98881700, 'Crystal Shark', '水晶鲨', 'クリスタル・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 1100, 800, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，以场上1只水属性怪兽为对象才能发动。这张卡特殊召唤，作为对象的怪兽的攻击力变成一半。这个效果特殊召唤的这张卡从场上离开的场合除外。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ②：把这张卡在「No.」怪兽的超量召唤使用的场合，可以把这张卡的等级当作3星或4星使用。'),
(7903368, 'Crystal Skull', '水晶头骨', '水晶ドクロ', 'Effect Monster', 'Rock', 'WATER', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤成功的场合发动。自己受到1000伤害。那之后，这张卡变成守备表示。 ②：自己没有受到效果伤害的回合的结束阶段才能发动。从卡组选1只攻击力0的岩石族怪兽加入手卡或特殊召唤。'),
(300302026, 'Crystal Transcendence', NULL, NULL, 'Skill Card', 'Jesse Anderso', NULL, NULL, NULL, NULL, NULL),
(47408488, 'Crystal Tree', '宝玉之树', '宝玉の樹', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次「宝玉兽」怪兽卡在魔法与陷阱区域被放置，给这张卡放置1个宝石指示物。 ②：把有宝石指示物放置的这张卡送去墓地才能发动。从卡组选这张卡放置的宝石指示物数量的「宝玉兽」怪兽当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(50954680, 'Crystal Wing Synchro Dragon', '水晶翼同步龙', 'クリスタルウィング・シンクロ・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 8, 3000, 2500, '调整＋调整以外的同调怪兽1只以上 ①：1回合1次，这张卡以外的怪兽的效果发动时才能发动。那个发动无效并破坏。这个效果破坏怪兽的场合，这张卡的攻击力直到回合结束时上升这个效果破坏的怪兽的原本攻击力数值。 ②：这张卡和5星以上的对方怪兽进行战斗的伤害计算时发动。这张卡的攻击力只在那次伤害计算时上升进行战斗的对方怪兽的攻击力数值。'),
(3576031, 'Crystolic Potential', '水晶阵 潜能', 'クリスタルP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的「水晶机巧」怪兽的攻击力·守备力上升300。 ②：自己·对方的结束阶段才能发动。自己从卡组抽出这个回合自己同调召唤的「水晶机巧」同调怪兽的数量。'),
(76359406, 'Crystron Ametrix', '水晶机巧－紫黄特力', '水晶機巧－アメトリクス', 'Synchro Monster', 'Machine', 'WATER', 5, 2500, 1500, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功的场合才能发动。对方场上的特殊召唤的表侧表示怪兽全部变成守备表示。 ②：同调召唤的这张卡被战斗·效果破坏的场合，以同调怪兽以外的自己墓地1只「水晶机巧」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(20050865, 'Crystron Citree', '水晶机巧－黄晶', '水晶機巧－シトリィ', 'Tuner Monster', 'Machine', 'WATER', 2, 500, 500, '这个卡名的效果1回合只能使用1次。 ①：对方的主要阶段以及战斗阶段，以调整以外的自己墓地1只怪兽为对象才能发动。那只怪兽效果无效特殊召唤，只用那只怪兽和这张卡为素材把1只机械族同调怪兽同调召唤。那个时候的同调素材怪兽不去墓地而除外。'),
(53829527, 'Crystron Cluster', '水晶机巧・晶簇', 'クリストロン・クラスター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的「水晶机巧」卡不能用对方的效果除外。 ②：以场上1张表侧表示卡为对象才能发动（自己场上有「水晶机巧」同调怪兽存在的场合，这个效果的对象可以变成2张）。「水晶机巧晶簇」以外的自己的墓地·除外状态的1张「水晶机巧」卡回到卡组，作为对象的卡破坏。'),
(47736165, 'Crystron Eleskeletus', '水晶机巧－骸晶凯特', '水晶機巧－エレスケルタス', 'Synchro Monster', 'Machine', 'WATER', 7, 2600, 2100, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。自己的墓地·除外状态的1张「水晶机巧」卡加入手卡。 ②：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力·守备力下降500。 ③：同调召唤的这张卡被战斗·效果破坏的场合才能发动。自己的墓地·除外状态的1只「水晶机巧」怪兽特殊召唤。'),
(52176579, 'Crystron Entry', '水晶机巧・乘舱', 'クリストロン・エントリー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「水晶机巧入舱」的②的效果1回合只能使用1次。 ①：从自己的手卡·墓地各选1只「水晶机巧」调整特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只「水晶机巧」怪兽为对象才能发动。把持有和那只怪兽的等级不同等级的1只「水晶机巧」怪兽从卡组送去墓地。作为对象的怪兽的等级变成和送去墓地的怪兽的等级相同。这个效果在这张卡送去墓地的回合不能发动。'),
(50588353, 'Crystron Halqifibrax', '水晶机巧－玻璃光纤', '水晶機巧－ハリファイバー', 'Link Monster', 'Machine', 'WATER', NULL, 1500, NULL, '包含调整的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从手卡·卡组把1只3星以下的调整守备表示特殊召唤。这个效果特殊召唤的怪兽在这个回合不能把效果发动。 ②：对方的主要阶段以及战斗阶段把场上的这张卡除外才能发动。从额外卡组把1只同调怪兽调整当作同调召唤作特殊召唤。'),
(65400671, 'Crystron Halqifibrax Prism', '水晶机巧－玻璃光纤 棱彩', '水晶機巧－ハリファイバーP', 'Link Monster', 'Machine', 'WATER', NULL, 1500, NULL, '包含调整的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。把持有那些作为连接素材的怪兽的原本等级合计以下的等级的1只调整从额外卡组守备表示特殊召唤。 ②：对方的主要阶段以及战斗阶段，把场上的这张卡除外才能发动。在自己场上把3只「水晶机巧衍生物」（机械族·水·1星·攻/守0）特殊召唤。这衍生物不能解放。'),
(99274184, 'Crystron Impact', '水晶机巧・冲击', 'クリストロン・インパクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以除外的1只自己的「水晶机巧」怪兽为对象才能发动。那只怪兽特殊召唤，对方场上有表侧表示怪兽存在的场合，那些对方怪兽的守备力变成0。 ②：自己场上的「水晶机巧」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个效果无效。这个效果在这张卡送去墓地的回合不能发动。'),
(31552317, 'Crystron Inclusion', '水晶机巧・内蕴', 'クリストロン・インクルージョン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把「水晶机巧包体」以外的1张「水晶机巧」卡加入手卡。 ②：自己的「水晶机巧」怪兽在1回合各有1次不会被战斗破坏。 ③：把墓地的这张卡除外，以自己墓地1只「水晶机巧」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(2743001, 'Crystron Phoenix', '水晶机巧－红凤席翁', '水晶機巧－フェニキシオン', 'Synchro Monster', 'Machine', 'WATER', 9, 2800, 2000, '同调怪兽调整＋调整以外的同调怪兽1只以上 ①：这张卡同调召唤成功的场合才能发动。对方的场上·墓地的魔法·陷阱卡全部除外。 ②：同调召唤的这张卡被战斗·效果破坏的场合，以这张卡以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(56049970, 'Crystron Prasiortle', '水晶机巧－绿晶龟', '水晶機巧－プラシレータ', 'Effect Monster', 'Machine', 'WATER', 2, 500, 2000, '「水晶机巧-绿晶龟」的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1张表侧表示的卡为对象才能发动。那张卡破坏，从卡组把1只「水晶机巧」调整特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族同调怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。从手卡把1只「水晶机巧」怪兽特殊召唤。'),
(93665266, 'Crystron Quan', '水晶机巧－石英', '水晶機巧－クオン', 'Tuner Monster', 'Machine', 'WATER', 1, 500, 500, '「水晶机巧-量子白晶」的效果1回合只能使用1次。 ①：对方的主要阶段以及战斗阶段才能发动。从手卡把1只调整以外的怪兽效果无效特殊召唤，只用那只怪兽和这张卡为素材把1只机械族同调怪兽同调召唤。'),
(39964797, 'Crystron Quandax', '水晶机巧－石英达姆', '水晶機巧－クオンダム', 'Synchro Tuner Monster', 'Machine', 'WATER', 4, 1800, 2000, '调整＋调整以外的怪兽1只以上 ①：对方的主要阶段以及战斗阶段才能发动。用包含这张卡的自己场上的怪兽为同调素材作同调召唤。 ②：同调召唤的这张卡被战斗·效果破坏的场合，以同调怪兽以外的自己墓地1只「水晶机巧」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(13455674, 'Crystron Quariongandrax', '水晶机巧－黄龙伽德', '水晶機巧－グリオンガンド', 'Synchro Monster', 'Machine', 'WATER', 9, 3000, 3000, '调整2只以上＋调整以外的怪兽1只 ①：这张卡同调召唤成功的场合，以最多有那些作为同调素材的怪兽数量的对方的场上·墓地的怪兽为对象才能发动。那些怪兽除外。 ②：同调召唤的这张卡被战斗·效果破坏的场合，以这张卡以外的除外的1只自己或者对方的怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。'),
(66938505, 'Crystron Rion', '水晶机巧－黑晶', '水晶機巧－リオン', 'Tuner Monster', 'Machine', 'WATER', 3, 500, 500, '「水晶机巧-胶子黑晶」的效果1回合只能使用1次。 ①：对方的主要阶段以及战斗阶段，以调整以外的除外的1只自己怪兽为对象才能发动。那只怪兽效果无效特殊召唤，只用那只怪兽和这张卡为素材把1只机械族同调怪兽同调召唤。那个时候的同调素材怪兽不去墓地回到持有者卡组。'),
(55326322, 'Crystron Rosenix', '水晶机巧－粉晶凤凰', '水晶機巧－ローズニクス', 'Effect Monster', 'Machine', 'WATER', 4, 1800, 1000, '「水晶机巧-红晶雀」的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1张表侧表示的卡为对象才能发动。那张卡破坏，从卡组把1只「水晶机巧」调整特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族同调怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。在自己场上把1只「水晶机巧衍生物」（机械族·水·1星·攻/守0）特殊召唤。这衍生物不能解放。'),
(83443619, 'Crystron Smiger', '水晶机巧－烟晶虎', '水晶機巧－スモーガー', 'Effect Monster', 'Machine', 'WATER', 3, 1000, 1800, '「水晶机巧-烟晶虎」的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1张表侧表示的卡为对象才能发动。那张卡破坏，从卡组把1只「水晶机巧」调整特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族同调怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1张「水晶机巧」魔法·陷阱卡加入手卡。'),
(25865565, 'Crystron Sulfador', '水晶机巧－柠晶法瓦多', '水晶機巧－サルファドール', 'Effect Monster', 'Machine', 'WATER', 5, 1900, 2250, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，以自己场上1张「水晶机巧」卡为对象才能发动。那张卡破坏，这张卡特殊召唤。这个回合，自己不是机械族怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「水晶机巧-柠晶救龙」以外的最多2张「水晶机巧」卡送去墓地（同名卡最多1张）。'),
(3422200, 'Crystron Sulfefnir', '水晶机巧－柠晶法夫纳', '水晶機巧－サルファフナー', 'Effect Monster', 'Machine', 'WATER', 5, 2000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，从手卡把「水晶机巧-柠晶龙」以外的1张「水晶机巧」卡丢弃才能发动。这张卡守备表示特殊召唤。那之后，自己场上1张卡破坏。 ②：场上的这张卡被战斗·效果破坏的场合才能发动。从卡组把1只「水晶机巧」怪兽守备表示特殊召唤。'),
(29838323, 'Crystron Thystvern', '水晶机巧－紫晶翼龙', '水晶機巧－シストバーン', 'Effect Monster', 'Machine', 'WATER', 3, 1500, 1500, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1张表侧表示的卡为对象才能发动。那张卡破坏，从卡组把1只「水晶机巧」调整特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族同调怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把「水晶机巧-紫晶龙」以外的1只「水晶机巧」怪兽加入手卡。'),
(55326323, 'Crystron Token', '水晶机巧－粉晶凤凰', '水晶機巧－ローズニクス', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(99471856, 'Crystron Tristaros', '水晶机巧－鳞龙石英', '水晶機巧－トリスタロス', 'Tuner Monster', 'Machine', 'WATER', 2, 800, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把效果发动时才能发动。从卡组把「水晶机巧-三位玉晶」以外的1只「水晶机巧」怪兽特殊召唤。那之后，用包含那只在内的自己场上的怪兽为素材进行1只机械族同调怪兽的同调召唤。 ②：把墓地的这张卡除外才能发动。自己场上1只同调怪兽破坏，从卡组把2只「水晶机巧」怪兽特殊召唤。这个回合，自己不是机械族怪兽不能从额外卡组特殊召唤。'),
(10789972, 'Cu Chulainn the Awakened', '觉醒战士 库丘林', '覚醒戦士 クーフーリン', 'Ritual Effect Monster', 'Warrior', 'LIGHT', 4, 500, 1000, '「觉醒之证」降临。1回合1次，选择自己墓地存在的1只通常怪兽才能发动。选择的怪兽从游戏中除外，直到下次的自己回合的准备阶段时这张卡的攻击力上升除外的那只通常怪兽的攻击力数值。'),
(17530001, 'Cuben', '魔方人', 'キューブン', 'Effect Monster', 'Thunder', 'LIGHT', 4, 600, 1900, '①：1回合1次，自己主要阶段才能发动。掷1次骰子。只要这只怪兽在场上表侧表示存在，双方不能把和出现的数目相同等级的怪兽召唤·特殊召唤。'),
(2434862, 'Cubic Ascension', '方界降世', '方界降世', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时才能发动。从卡组把1只「方界胤 毗贾姆」特殊召唤，攻击对象转移为那只怪兽进行伤害计算。 ②：自己基本分比对方少2000以上的场合，把墓地的这张卡除外才能发动。从自己的手卡·卡组·墓地选1只「方界胤 毗贾姆」特殊召唤。只有对方场上才有怪兽存在的状态发动的场合，可以再选最多2只「方界胤 毗贾姆」特殊召唤。'),
(38606913, 'Cubic Causality', '方界缘起', '方界縁起', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把最多有自己场上的「方界」怪兽数量的方界指示物给对方场上的表侧表示怪兽放置。有方界指示物放置的怪兽不能攻击，效果无效化。 ②：把墓地的这张卡除外，以自己场上1只「方界」怪兽为对象才能发动。这个回合，每次那只怪兽战斗破坏有方界指示物放置的怪兽，给与对方那只破坏的怪兽的原本攻击力数值的伤害。'),
(1218214, 'Cubic Dharma', '方界法', '方界法', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1张「方界」卡送去墓地，自己从卡组抽1张。 ②：只要这张卡在魔法与陷阱区域存在，自己的「方界」怪兽的战斗发生的对自己的战斗伤害变成0。 ③：把墓地的这张卡除外，以自己墓地1只「方界」怪兽为对象才能发动。那只怪兽加入手卡。'),
(9659580, 'Cubic Karma', '方界业', '方界業', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡的发动时，可以以「方界胤 毗贾姆」以外的自己场上1只「方界」怪兽为对象。那个场合，从手卡·卡组把「方界胤 毗贾姆」任意数量送去墓地。那之后，作为对象的怪兽的攻击力上升这个效果送去墓地的怪兽数量×800。 ②：对方回合「方界」怪兽的效果让「方界胤 毗贾姆」特殊召唤的场合发动。这张卡送去墓地，对方基本分变成一半。 ③：把墓地的这张卡除外才能发动。从卡组把1只「方界」怪兽加入手卡。'),
(8837932, 'Cubic Mandala', '方界曼荼罗', '方界曼荼羅', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上有「方界」怪兽存在的场合，以这个回合被破坏送去对方墓地的怪兽任意数量为对象才能把这张卡发动。那些怪兽的攻击力变成0在对方场上特殊召唤，给那些怪兽各放置1个方界指示物。有方界指示物放置的怪兽不能攻击，效果无效化。 ②：只要作为对象的怪兽在对方场上存在，对方发动的怪兽的效果无效化。 ③：作为对象的怪兽全部从场上离开的场合这张卡破坏。'),
(71442223, 'Cubic Rebirth', '方界轮回', '方界輪廻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的直接攻击宣言时，以那1只攻击怪兽为对象才能发动。对方把那些同名怪兽尽可能从自身的手卡·卡组·墓地攻击表示特殊召唤。作为对象的怪兽以及这个效果特殊召唤的怪兽的攻击力变成0，给那些怪兽各放置1个方界指示物。有方界指示物放置的怪兽不能攻击，效果无效化。并且，再从自己手卡把1只4星以下的「方界」怪兽无视召唤条件特殊召唤。'),
(35058588, 'Cubic Wave', '方界波动', '方界波動', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「方界」怪兽和对方场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的攻击力变成2倍，那只对方怪兽的攻击力变成一半。 ②：从自己墓地把这张卡和「方界」怪兽任意数量除外，以除外的「方界」怪兽数量的对方场上的表侧表示怪兽为对象才能发动。给那些怪兽各放置1个方界指示物。有方界指示物放置的怪兽不能攻击，效果无效化。'),
(89552119, 'Cucumber Horse', '精灵冥骑-急还马', '精霊冥騎－急還馬', 'Effect Monster', 'Plant', 'DARK', 8, 100, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：战斗阶段以外，怪兽区域的这张卡送去墓地。 ②：这张卡在墓地存在的场合，自己·对方的战斗阶段开始时，从手卡以及自己场上的表侧表示怪兽之中把1只植物族怪兽送去墓地才能发动。这张卡特殊召唤。那之后，可以从自己或者对方的墓地选1只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽全部在战斗阶段结束时送去墓地。'),
(27178262, 'Cunning of the Six Samurai', '六武众之理', '六武衆の理', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只名字带有「六武众」的怪兽送去墓地才能发动。选择自己或者对方的墓地1只名字带有「六武众」的怪兽在自己场上特殊召唤。'),
(37812118, 'Cup of Ace', '圣杯Ace', 'カップ・オブ・エース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：进行1次投掷硬币。表的场合，自己从卡组抽2张。里的场合，对方从卡组抽2张。'),
(69526976, 'Cupid Dunk', '篮邱比特', 'ロー・キューピット', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 600, '①：这张卡不会被和除持有比这张卡高的等级的怪兽以外的怪兽的战斗破坏。 ②：自己准备阶段才能发动。这张卡的等级上升1星。'),
(35960413, 'Cupid Fore', '高邱比特', 'コウ・キューピット', 'Effect Monster', 'Fairy', 'LIGHT', 6, 2200, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的怪兽只有守备力600的怪兽的场合才能发动。这张卡从手卡特殊召唤。 ②：丢弃1张手卡，以自己场上1只天使族·光属性怪兽和场上1只表侧表示怪兽为对象才能发动。那只自己怪兽的等级直到回合结束时变成和另1只怪兽的等级相同。这个效果在对方回合也能发动。'),
(21915012, 'Cupid Pitch', '垒邱比特', 'ルイ・キューピット', 'Synchro Tuner Monster', 'Fairy', 'LIGHT', 4, NULL, 600, '调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡同调召唤的场合发动。这张卡的等级上升或下降那只作为同调素材的调整的等级数值。 ②：这张卡的攻击力上升这张卡的等级×400。 ③：同调召唤的这张卡作为同调素材送去墓地的场合发动。给与对方这张卡为同调素材的同调怪兽的等级×100伤害，可以从卡组把1只8星以下而守备力600的怪兽加入手卡。'),
(1566817, 'Cupid Serve', '网邱比特', 'テイ・キューピット', 'Effect Monster', 'Fairy', 'LIGHT', 2, 1000, 600, '这个卡名的②的效果1回合只能有1次。 ①：这张卡只要在怪兽区域存在，不受除持有这张卡的等级以下的等级的怪兽以外的全部怪兽发动的效果影响。 ②：把自己墓地最多3张卡除外才能发动。直到回合结束时，这张卡的等级上升除外数量的数值。'),
(11851647, 'Cupid Volley', '排邱比特', 'ハイ・キューピット', 'Effect Monster', 'Fairy', 'LIGHT', 1, 600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己卡组上面把最多3张卡送去墓地才能发动。这张卡的等级直到回合结束时上升因为这个效果发动而送去墓地的卡数量的数值。 ②：场上的这张卡被对方破坏送去墓地的场合发动。自己回复1500基本分。'),
(31603289, 'Cupsy★Yummy Way', '杯糕喵★黯蜜味', 'カプシー★ヤミーウェイ', 'Synchro Tuner Monster', 'Beast', 'LIGHT', 2, NULL, 2200, '调整＋调整以外的怪兽1只 这张卡同调召唤的场合，可以把自己场上1只连接1怪兽当作1星调整使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把2只「味美喵」怪兽加入手卡。那之后，选自己1张手卡丢弃。 ②：对方把魔法·陷阱·怪兽的效果发动时，让这张卡回到额外卡组才能发动。从自己墓地把最多2只「味美喵」怪兽特殊召唤。'),
(31425736, 'Cupsy☆Yummy', '杯糕喵☆黯蜜', 'カプシー☆ヤミー', 'Effect Monster', 'Beast', 'LIGHT', 1, NULL, 1600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：连接1怪兽或者2星同调怪兽在自己场上存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「奶油蛋糕杯猫☆味美喵」以外的1张「味美喵」卡加入手卡。同调怪兽的效果特殊召唤的场合，作为代替让自己也能抽1张。'),
(85802526, 'Cure Mermaid', '人鱼公主', 'プリンセス人魚', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 800, '只要这张卡在自己场上表侧表示的存在，每次自己的准备阶段回复800基本分。'),
(98095162, 'Curious, the Lightsworn Dominion', '光道主宰者 居理阿斯', 'ライトロード・ドミニオン キュリオス', 'Link Monster', 'Warrior', 'LIGHT', NULL, 2400, NULL, '相同属性而种族不同的怪兽3只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组选1张卡送去墓地。 ②：自己卡组的卡被效果送去墓地的场合发动。从自己卡组上面把3张卡送去墓地。 ③：表侧表示的这张卡因对方的效果从场上离开的场合或者被战斗破坏的场合，以自己墓地1张卡为对象才能发动。那张卡加入手卡。'),
(14509651, 'Curse Necrofear', '诅咒人偶 妮可罗菲娅', 'カース・ネクロフィア', 'Effect Monster', 'Fiend', 'DARK', 8, 2800, 2200, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：以除外的3只自己的恶魔族怪兽为对象才能发动。这张卡从手卡特殊召唤，作为对象的怪兽回到卡组。 ②：怪兽区域的这张卡被对方破坏送去墓地的回合的结束阶段发动。这张卡从墓地特殊召唤。那之后，可以选最多有自己场上的魔法·陷阱卡的卡名种类数量的对方场上的卡破坏。'),
(41398771, 'Curse of Aging', '老化的诅咒', '老化の呪い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡丢弃1枚卡，在回合终了前，对方场上所有怪兽攻击力·守备力下降500点。'),
(66742250, 'Curse of Anubis', '阿努比斯的诅咒', 'アヌビスの呪い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的攻击表示的效果怪兽全部变成守备表示。这个回合，这个效果变成守备表示的怪兽原本守备力变成0，不能把表示形式变更。'),
(34690953, 'Curse of Aramatir', '禁咒 菈玛启崇颂', '禁呪アラマティア', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。在自己或者对方场上把1只「勇者衍生物」（天使族·地·4星·攻/守2000）特殊召唤。那之后，选自己1张手卡送去墓地。这个效果发动的回合，自己若非「勇者衍生物」以及有那个衍生物名记述的怪兽则不能特殊召唤。 ②：自己场上的怪兽被战斗·效果破坏的场合才能发动。在自己或者对方场上把1只「勇者衍生物」特殊召唤。'),
(84970821, 'Curse of Darkness', '暗黑之咒缚', '暗黒の呪縛', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次自己或者对方把魔法卡发动给与那个发动的玩家1000伤害。'),
(64998567, 'Curse of Diabell', '迪亚贝尔的诅咒', 'カース・オブ・ディアベル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「迪亚贝尔」怪兽2只以上存在的场合，把自己场上1只怪兽送去墓地才能发动。对方场上的表侧表示卡全部破坏。 ②：这张卡从手卡·卡组中送去墓地的场合或者从中除外的场合才能发动。从卡组把「恶魔迪亚贝尔的诅咒」以外的1张「迪亚贝尔」魔法·陷阱卡加入手卡。'),
(28279543, 'Curse of Dragon', '诅咒之龙', 'カース・オブ・ドラゴン', 'Normal Monster', 'Dragon', 'DARK', 5, 2000, 1500, '邪恶之龙。使用黑暗力量的攻击强而有力。'),
(61525276, 'Curse of Dragon, the Cursed Dragon', '咒缠龙－诅咒之龙', '呪われし竜－カース・オブ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 5, 2000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把有「龙骑士 盖亚」的卡名记述的1张魔法·陷阱卡加入手卡。 ②：这张卡被送去墓地的场合，以自己场上1只「龙骑士 盖亚」为对象才能发动。持有那只怪兽的攻击力以下的攻击力的对方场上的全部表侧表示怪兽的效果直到回合结束时无效化。'),
(72064891, 'Curse of Dragon, the Magical Knight Dragon', '魔道骑龙 诅咒之龙', '魔道騎竜カース・オブ・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 5, 2000, 1500, '战士族怪兽＋5星以上的龙族怪兽 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤成功的场合，以有「龙骑士 盖亚」的卡名记述的自己墓地1张魔法·陷阱卡为对象才能发动。那张卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己把龙族·7星怪兽融合召唤的场合，也能把自己墓地的怪兽除外作为融合素材。'),
(7241272, 'Curse of Dragonfire', '狱炎的诅咒之龙', '獄炎のカース・オブ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 5, 2000, 1500, '①：这张卡召唤·特殊召唤成功的场合，以场上1张场地魔法卡为对象才能发动。那张卡破坏。 ②：1回合1次，自己主要阶段才能发动。融合怪兽卡决定的包含这张卡的融合素材怪兽从自己场上送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(12470447, 'Curse of Fiend', '邪恶的仪式', '邪悪な儀式', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '场上全部怪兽的表示形式交换。发动回合，怪兽的表示形式不能变更。这张卡只能在准备阶段发动。'),
(2926176, 'Curse of Royal', '王家的诅咒', '王家の呪い', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：只以场上的魔法·陷阱卡1张为对象并要让那张卡破坏的魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(94749594, 'Curse of the Ancient Turtle', '古代龟的诅咒', '古代亀の呪い', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1只不死族怪兽除外才能发动。从卡组把1只不死族怪兽送去墓地。 ②：自己的不死族怪兽被战斗破坏时，把墓地的这张卡除外才能发动。从卡组把1只守备力2000以下的不死族怪兽特殊召唤。'),
(12863633, 'Curse of the Circle', '五棱星之咒缚', '五稜星の呪縛', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择对方场上存在的1只怪兽发动。对方不能把选择的怪兽解放，也不能作为同调素材。'),
(94377247, 'Curse of the Masked Beast', '假面魔兽的仪式', '仮面魔獣の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「假面魔兽 鬼面修道士」的降临必需。 ①：从自己的手卡·场上把等级合计直到8以上的怪兽解放，从手卡把「假面魔兽 鬼面修道士」仪式召唤。'),
(81788994, 'Curse of the Shadow Prison', '影牢之咒缚', '影牢の呪縛', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：每次「影依」怪兽被效果送去墓地，每有1只给这张卡放置1个魔石指示物。 ②：对方场上的怪兽的攻击力在对方回合内下降这张卡的魔石指示物数量×100。 ③：每次自己把「影依」融合怪兽融合召唤有1次，可以把这张卡3个魔石指示物取除把对方场上1只表侧表示怪兽作为融合素材。'),
(33391067, 'Curse Reflection Doll', '反弹诅咒的纸人', '呪詛返しのヒトガタ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：给与自己伤害的怪兽的效果发动时才能发动。那个效果发生的对自己的效果伤害由对方代受。 ②：这张卡在墓地存在，自己受到战斗伤害时才能发动。这张卡在自己场上盖放。'),
(98867329, 'Cursed Armaments', '灾厄的装备品', '災いの装備品', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力下降自己场上存在的怪兽数量×600的数值。这张卡从场上送去墓地时，可以选择对方场上表侧表示存在的1只怪兽把这张卡装备。'),
(42199039, 'Cursed Bamboo Sword', '妖刀竹光', '妖刀竹光', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升0。 ②：以自己场上1张其他的「竹光」卡为对象才能发动。那张卡回到手卡，装备怪兽在这个回合可以直接攻击。 ③：这张卡被送去墓地的场合才能发动。从卡组把「妖刀竹光」以外的1张「竹光」卡加入手卡。'),
(46967601, 'Cursed Bill', '诅咒纸符', '呪いのお札', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽被破坏让这张卡送去墓地时，给与装备怪兽的控制者基本分送去墓地的装备怪兽的原本守备力数值的伤害。'),
(71545247, 'Cursed Bride Doll', '于归世佳偶', '離世召人形', 'Tuner Monster', 'Spellcaster', 'EARTH', 3, NULL, 2100, '①：把这张卡抽到时，把这张卡给对方观看才能发动。这张卡特殊召唤。 ②：自己·对方的战斗阶段开始时发动。自己卡组的数量比对方多的场合，这张卡的攻击力直到回合结束时上升那个相差数量×300。 ③：这张卡被送去墓地的回合的结束阶段发动。这张卡回到卡组最上面。'),
(23249029, 'Cursed Copycat Noble Arms', '咒怨仿品·圣剑', NULL, 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽的攻击力·守备力上升自己场上或墓地的装备魔法卡的数量×200。 这张卡给战士族怪兽装备中的场合：可以把这个效果发动；直到回合结束时，自己不是战士族怪兽不能特殊召唤，从卡组把属性·等级和装备怪兽相同而卡名不同的1只战士族怪兽特殊召唤，这张卡给那只怪兽装备，那之后，把这张卡装备过的怪兽破坏。「咒怨仿品·圣剑」的这个效果1回合只能使用1次。'),
(31434645, 'Cursed Eldland', '被诅咒的埃尔德兰德', '呪われしエルドランド', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己不用不死族怪兽不能攻击宣言。 ②：支付800基本分才能发动。从卡组把1只「黄金国巫妖」怪兽或1张「黄金乡」魔法·陷阱卡加入手卡。 ③：这张卡从魔法与陷阱区域送去墓地的场合才能发动。从卡组把1只「黄金国巫妖」怪兽或1张「黄金乡」魔法·陷阱卡送去墓地。'),
(18489208, 'Cursed Fig', '被诅咒的无花果', 'カースド・フィグ', 'Effect Monster', 'Plant', 'WATER', 1, 200, 200, '这张卡被战斗破坏送去墓地时，选择场上盖放的2张魔法·陷阱卡发动。只要这张卡在墓地存在，选择的卡不能发动。'),
(26857786, 'Cursed Fire King Doom Burst', '咒炎王 爆咒', '呪炎王 バースト・カースド', 'Effect Monster', 'Fiend', 'FIRE', 3, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有恶魔族调整存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降600。 ③：这张卡被战斗·效果破坏送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降400。'),
(58851034, 'Cursed Seal of the Forbidden Spell', '封魔的咒印', '封魔の呪印', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '从自己手卡中丢弃1张魔法卡。使魔法卡的发动及效果无效，并且将其破坏。对方在本次决斗中不能再发动因这张卡效果而被破坏的魔法卡及其同名卡。'),
(22026707, 'Curtain of the Dark Ones', '黑魔族的帘布', '黒魔族のカーテン', 'Normal Monster', 'Spellcaster', 'DARK', 2, 600, 500, '魔术师制作的窗帘。据说可以提升魔法师的力量。'),
(68756810, 'Cutter Shark', '切入鲨', 'カット・イン・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, NULL, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，只让自己场上的怪兽1只成为攻击·效果的对象时，把那只怪兽解放才能发动。这张卡特殊召唤。 ②：这张卡特殊召唤的场合才能发动。这个回合的结束阶段，从自己墓地把「切入鲨」以外的1只水属性怪兽加入手卡。'),
(67926903, 'CXyz Barian Hope', '混沌超量 冀望皇巴利安', 'CX 冀望皇バリアン', 'XYZ Monster', 'Warrior', 'LIGHT', 7, NULL, NULL, '7星怪兽×3只以上 这张卡也能在自己场上的「混沌No.101」～「混沌No.107」其中任意种的「混沌No.」怪兽上面重叠来超量召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升这张卡的超量素材数量×1000。 ②：以自己墓地1只「No.」怪兽为对象才能发动。直到对方结束阶段，这张卡得到和那只怪兽的原本的卡名·效果相同的卡名·效果。'),
(76419637, 'CXyz Battleship Cherry Blossom', '混沌超量 激烈华战舰 手弱女', 'CX 激烈華戦艦タオヤメ', 'XYZ Monster', 'Plant', 'EARTH', 4, 2400, 2000, '4星怪兽×4 对方的结束阶段时只有1次在对方手卡比自己手卡多的场合发动。对方选1张手卡丢弃。此外，这张卡有「烈华炮舰 抚子」在作为超量素材的场合，得到以下效果。 ●把这张卡1个超量素材取除才能发动。给与对方基本分场上的卡数量×300的数值的伤害。「混沌超量 激烈华战舰 手弱女」的这个效果1回合只能使用1次。'),
(88754763, 'CXyz Coach Lord Ultimatrainer', '混沌超量 热血指导神 究极训练师', 'CX 熱血指導神アルティメットレーナー', 'XYZ Monster', 'Warrior', 'FIRE', 9, 3800, 2300, '9星怪兽×4 场上的这张卡不会成为卡的效果的对象。此外，这张卡有超量怪兽在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除才能发动。从卡组抽1张卡，给双方确认。确认的卡是怪兽的场合，再给与对方基本分800分伤害。'),
(13030280, 'CXyz Comics Hero Legend Arthur', '混沌超量 漫画英雄 传奇亚瑟', 'CX－CHレジェンド・アーサー', 'XYZ Monster', 'Warrior', 'EARTH', 5, 3000, 2400, '5星怪兽×3 这张卡1回合只有1次不会被战斗破坏。此外，这张卡有「漫画英雄 亚瑟王」在作为超量素材的场合，得到以下效果。 ●这张卡战斗破坏怪兽送去墓地时，把这张卡1个超量素材取除才能发动。破坏的怪兽从游戏中除外，给与对方基本分那个原本攻击力数值的伤害。'),
(23454876, 'CXyz Dark Fairy Cheer Girl', '混沌超量 暗黑妖精啦啦队少女', 'CX ダーク・フェアリー・チア・ガール', 'XYZ Monster', 'Fairy', 'DARK', 5, 2500, 1900, '5星怪兽×3 这张卡从场上送去墓地时，从卡组抽1张卡。此外，这张卡有「妖精啦啦队少女」在作为超量素材的场合，得到以下效果。 ●这张卡战斗破坏对方怪兽时，把这张卡1个超量素材取除才能发动。给与对方基本分自己手卡数量×400的数值的伤害。'),
(3685372, 'CXyz Gimmick Puppet Fanatix Machinix', '混沌超量 机关傀偶－迷狂机械神', 'CX ギミック・パペット－ファナティクス・マキナ', 'XYZ Monster', 'Machine', 'DARK', 9, 3100, 1500, '9星怪兽×3 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「人偶」陷阱卡加入手卡。 ②：把这张卡1个超量素材取除才能发动。从自己或对方的墓地把1只怪兽在对方场上守备表示特殊召唤。 ③：对方场上有怪兽特殊召唤的场合，以那之内的1只为对象才能发动。那只怪兽破坏，给与对方那个原本攻击力一半数值的伤害。'),
(41309158, 'CXyz Mechquipped Djinn Angeneral', '混沌超量 机装魔人 引擎天将', 'CX 機装魔人エンジェネラル', 'XYZ Monster', 'Fairy', 'DARK', 4, 2600, 1600, '4星怪兽×3 这张卡超量召唤成功时，可以选择场上守备表示存在的1只怪兽变成表侧攻击表示。此外，这张卡有「机装天使 引擎天兵」在作为超量素材的场合，得到以下效果。 ●这张卡给与对方基本分战斗伤害时，把这张卡1个超量素材取除才能发动。给与对方基本分1000分伤害。'),
(61374414, 'CXyz N.As.Ch. Knight', '混沌超量－沉魂救济混沌骑士', 'CX－N・As・Ch Knight', 'XYZ Monster', 'Aqua', 'WATER', 6, 2000, 3000, '6星怪兽×3 这张卡也能在自己场上的「伟人庇护战车骑士」上面重叠来超量召唤。这个卡名的②的效果1回合只能使用1次。 ①：场上的这张卡不会被效果破坏。 ②：把这张卡1个超量素材取除才能发动。把1只「No.101」～「No.107」其中任意种的「No.」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽在下次的对方结束阶段破坏。'),
(41147577, 'CXyz Simon the Great Moral Leader', '混沌超量 风纪大宫司 祭文', 'CX 風紀大宮司サイモン', 'XYZ Monster', 'Spellcaster', 'LIGHT', 7, 3000, 2500, '7星怪兽×3 这张卡不受这张卡以外的怪兽的效果影响。此外，这张卡有「风纪宫司 祝词」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，选择对方场上1只怪兽才能发动。选择的怪兽的表示形式变更，那只怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(49202331, 'CXyz Skypalace Babylon', '混沌超量 超巨大空中要塞 宝比伦号', 'CX 超巨大空中要塞バビロン', 'XYZ Monster', 'Machine', 'WIND', 11, 3800, 4000, '11星怪兽×3 这张卡战斗破坏怪兽送去墓地时，给与对方基本分破坏的怪兽的原本攻击力一半数值的伤害。此外，这张卡有「超巨大空中宫殿 钟声协和号」在作为超量素材的场合，得到以下效果。 ●这张卡战斗破坏怪兽的场合，可以通过把这张卡1个超量素材取除，只再1次可以继续攻击。这个效果1回合只能使用1次。'),
(77235086, 'Cyber Angel Benten', '电子天使－弁天－', 'サイバー・エンジェル－弁天－', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 6, 1800, 1500, '「机械天使的仪式」降临。 ①：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本守备力数值的伤害。 ②：这张卡被解放的场合才能发动。从卡组把1只天使族·光属性怪兽加入手卡。'),
(39618799, 'Cyber Angel Dakini', '电子天使－荼吉尼－', 'サイバー・エンジェル－荼吉尼－', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 8, 2700, 2400, '「机械天使的仪式」降临。 ①：这张卡仪式召唤成功的场合才能发动。对方必须把自身场上1只怪兽送去墓地。 ②：只要这张卡在怪兽区域存在，自己的仪式怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：自己结束阶段以自己墓地1只仪式怪兽或者1张「机械天使的仪式」为对象才能发动。那张卡加入手卡。'),
(3629090, 'Cyber Angel Idaten', '电子天使－韦驮天－', 'サイバー・エンジェル－韋駄天－', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 6, 1600, 2000, '「机械天使的仪式」降临。 ①：这张卡仪式召唤成功的场合才能发动。从自己的卡组·墓地选1张仪式魔法卡加入手卡。 ②：这张卡被解放的场合才能发动。自己场上的全部仪式怪兽的攻击力·守备力上升1000。'),
(91668401, 'Cyber Angel Izana', '电子天使－伊舍那－', 'サイバー・エンジェル－伊舎那－', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 8, 2500, 2600, '「机械天使的仪式」降临。 ①：这张卡仪式召唤成功的场合才能发动。对方必须把自身场上1张魔法·陷阱卡送去墓地。 ②：这张卡的攻击破坏对方怪兽送去墓地时才能发动。这张卡只再1次可以继续向对方怪兽攻击。 ③：1回合1次，自己场上的「电子化天使」仪式怪兽为对象的对方的效果发动时才能发动。选自己墓地1只仪式怪兽回到卡组，选对方场上1张卡破坏。'),
(99427357, 'Cyber Angel Natasha', '电子天使－那沙帝弥－', 'サイバー・エンジェル－那沙帝弥－', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 5, 1000, 1000, '「机械天使的仪式」降临。 ①：1回合1次，以自己场上1只表侧表示怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力一半的数值。 ②：自己的仪式怪兽被选择作为攻击对象时才能发动。那次攻击无效。 ③：这张卡在墓地存在的场合，从自己墓地把这张卡以外的1只「电子化天使」怪兽除外，以对方场上1只怪兽为对象才能发动。这张卡从墓地特殊召唤，得到作为对象的怪兽的控制权。'),
(78316184, 'Cyber Angel Vrash', '电子天使－美朱濡－', 'サイバー・エンジェル－美朱濡－', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 10, 3000, 2000, '「机械天使的仪式」降临。 ①：这张卡仪式召唤成功的场合才能发动。从额外卡组特殊召唤的对方场上的怪兽全部破坏，给与对方破坏的怪兽数量×1000伤害。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。 ②：1回合1次，要让场上的卡破坏的魔法·陷阱·怪兽的效果发动时，让自己墓地1只仪式怪兽回到卡组才能发动。那个发动无效并破坏。'),
(59907935, 'Cyber Archfiend', '电子化恶魔', 'サイバーデーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 2000, '自己的抽卡阶段开始时，若自己手卡为0张的场合，经过通常抽卡后可以再抽1张。自己的结束阶段时手卡有1张以上的场合，这张卡破坏。'),
(68774379, 'Cyber Barrier Dragon', '电子障壁龙', 'サイバー・バリア・ドラゴン', 'Effect Monster', 'Machine', 'LIGHT', 6, 800, 2800, '这张卡不能通常召唤。这张卡只能通过「攻击反射装置」的效果特殊召唤。这张卡攻击表示的场合，1回合1次，可以把1只对方怪兽的攻击无效。'),
(300302027, 'Cyber Blade Fusion', NULL, NULL, 'Skill Card', 'Alexis Rhodes', NULL, NULL, NULL, NULL, NULL),
(10248389, 'Cyber Blader', '电子化冰刀手', 'サイバー・ブレイダー', 'Fusion Monster', 'Warrior', 'EARTH', 7, 2100, 800, '「电子化明星」＋「利刃滑冰者」 这张卡的融合召唤不用上记的卡不能进行。 ①：对方场上的怪兽数量让这张卡得到以下效果。 ●1只：这张卡不会被战斗破坏。 ●2只：这张卡的攻击力变成2倍。 ●3只：对方发动的魔法·陷阱·怪兽的效果无效化。'),
(6400512, 'Cyber Commander', '突击兵', 'コマンダー', 'Normal Monster', 'Machine', 'DARK', 2, 750, 700, '装备火箭发射器与反坦克火箭炮的实战部队。'),
(39439590, 'Cyber Dinosaur', '电子恐龙', 'サイバー・ダイナソー', 'Effect Monster', 'Machine', 'LIGHT', 7, 2500, 1900, '对方从手卡特殊召唤怪兽时，可以从手卡特殊召唤这张卡。'),
(70095154, 'Cyber Dragon', '电子龙', 'サイバー・ドラゴン', 'Effect Monster', 'Machine', 'LIGHT', 5, 2100, 1600, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(23893227, 'Cyber Dragon Core', '电子龙核', 'サイバー・ドラゴン・コア', 'Effect Monster', 'Machine', 'LIGHT', 2, 400, 1500, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：这张卡召唤的场合发动。从卡组把1张「电子」魔法·陷阱卡或「电子科技」魔法·陷阱卡加入手卡。 ③：只有对方场上才有怪兽存在的场合，把墓地的这张卡除外才能发动。从卡组把1只「电子龙」怪兽特殊召唤。'),
(59281922, 'Cyber Dragon Drei', '电子龙三代', 'サイバー・ドラゴン・ドライ', 'Effect Monster', 'Machine', 'LIGHT', 4, 1800, 800, '①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：这张卡召唤成功时才能发动。自己场上的全部「电子龙」的等级变成5星。这个效果发动的回合，自己不是机械族怪兽不能特殊召唤。 ③：这张卡被除外的场合，以自己场上1只「电子龙」为对象才能发动。这个回合，那只怪兽不会被战斗·效果破坏。'),
(56364287, 'Cyber Dragon Herz', '电子龙芯', 'サイバー・ドラゴン・ヘルツ', 'Effect Monster', 'Machine', 'LIGHT', 1, 100, 100, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：这张卡的卡名只要在场上·墓地存在当作「电子龙」使用。 ②：这张卡特殊召唤的场合才能发动。这张卡的等级直到回合结束时变成5星。这个效果的发动后，直到回合结束时自己不是机械族怪兽不能特殊召唤。 ③：这张卡被送去墓地的场合才能发动。从自己的卡组·墓地把这张卡以外的1只「电子龙」加入手卡。'),
(10443957, 'Cyber Dragon Infinity', '电子龙无限', 'サイバー・ドラゴン・インフィニティ', 'XYZ Monster', 'Machine', 'LIGHT', 6, 2100, 1600, '机械族·光属性6星怪兽×3 「电子龙·无限」1回合1次也能在自己场上的「电子龙·新星」上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材数量×200。 ②：1回合1次，以场上1只表侧攻击表示怪兽为对象才能发动。那只怪兽作为这张卡的超量素材。 ③：1回合1次，魔法·陷阱·怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。');